/** A sheet's pools and their members. The signed-in user's name comes in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/pools")
public class PoolController {

    private static final BigDecimal HUNDRED = new BigDecimal("100.00");

    /** A member, a person or another pool (poolId set, never retired): a retired person (a retirement date set,
     *  whatever the date) counts 0.00 toward the total. Its cut of the pool's pot (two decimals); none when the
     *  pool is unbalanced or has no pot. */
    public record PoolMemberView(Long personId, Long poolId, String name, String share, boolean retired, String cut) {
    }

    /** A pool, with its total share and whether that is exactly 100.00. */
    public record PoolView(long id, String name, List<PoolMemberView> members, String totalShare, boolean balanced) {

        /** The sheet's pools as views, in their order. A pool that is a member of another has as its pot its cut
         *  in the pool above (none when that is unbalanced or has none); one that is a member of none has the
         *  sheet's pot. */
        static List<PoolView> of(List<Pool> pools, Map<Long, Person> people, BigDecimal sheetPot) {
            Map<Long, Pool> byId = new HashMap<>();
            Map<Long, Pool> parentOf = new HashMap<>();
            for (Pool pool : pools) {
                byId.put(pool.getId(), pool);
                for (PoolMember m : pool.getMembers()) {
                    if (m.getMemberPoolId() != null) {
                        parentOf.put(m.getMemberPoolId(), pool);
                    }
                }
            }
            Map<Long, PoolView> views = new HashMap<>();
            for (Pool pool : pools) {
                view(pool, byId, parentOf, people, sheetPot, views);
            }
            return pools.stream().map(p -> views.get(p.getId())).toList();
        }

        private static PoolView view(Pool pool, Map<Long, Pool> byId, Map<Long, Pool> parentOf,
                Map<Long, Person> people, BigDecimal sheetPot, Map<Long, PoolView> views) {
            PoolView done = views.get(pool.getId());
            if (done != null) {
                return done;
            }
            BigDecimal pot = sheetPot;
            Pool parent = parentOf.get(pool.getId());
            if (parent != null) {
                PoolView above = view(parent, byId, parentOf, people, sheetPot, views);
                String cut = above.members().stream().filter(m -> pool.getId().equals(m.poolId())).findFirst()
                        .map(PoolMemberView::cut).orElse(null);
                pot = cut == null ? null : new BigDecimal(cut);
            }
            PoolView v = of(pool, byId, people, pot);
            views.put(pool.getId(), v);
            return v;
        }

        private static PoolView of(Pool pool, Map<Long, Pool> pools, Map<Long, Person> people, BigDecimal pot) {
            List<PoolMember> all = pool.getMembers();
            BigDecimal total = BigDecimal.ZERO.setScale(2);
            boolean[] retired = new boolean[all.size()];
            for (int i = 0; i < all.size(); i++) {
                Long personId = all.get(i).getPersonId();
                Person p = personId == null ? null : people.get(personId);
                retired[i] = p != null && p.isRetired();
                if (!retired[i]) {
                    total = total.add(all.get(i).getShare());
                }
            }
            boolean balanced = total.compareTo(HUNDRED) == 0;
            BigDecimal[] cuts = balanced && pot != null ? cuts(all, retired, pot) : new BigDecimal[all.size()];
            List<PoolMemberView> members = new ArrayList<>();
            for (int i = 0; i < all.size(); i++) {
                PoolMember m = all.get(i);
                String name;
                if (m.getMemberPoolId() != null) {
                    Pool member = pools.get(m.getMemberPoolId());
                    name = member == null ? "" : member.getName();
                } else {
                    Person p = people.get(m.getPersonId());
                    name = p == null ? "" : p.getName();
                }
                members.add(new PoolMemberView(m.getPersonId(), m.getMemberPoolId(), name,
                        m.getShare().setScale(2).toPlainString(), retired[i],
                        cuts[i] == null ? null : cuts[i].toPlainString()));
            }
            return new PoolView(pool.getId(), pool.getName(), members, total.setScale(2).toPlainString(), balanced);
        }

        /** Each member's cut of the pot: the pot times their share divided by 100, rounded half to even to two
         *  decimals (0.00 for a retired one); the remainder, the pot minus the cuts added up, goes to the member
         *  with the largest share, the earliest added on a tie, so the cuts total exactly the pot. */
        private static BigDecimal[] cuts(List<PoolMember> members, boolean[] retired, BigDecimal pot) {
            BigDecimal[] cuts = new BigDecimal[members.size()];
            BigDecimal sum = BigDecimal.ZERO.setScale(2);
            int largest = -1;
            for (int i = 0; i < members.size(); i++) {
                BigDecimal share = members.get(i).getShare();
                cuts[i] = retired[i] ? BigDecimal.ZERO.setScale(2)
                        : pot.multiply(share).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
                sum = sum.add(cuts[i]);
                if (!retired[i] && (largest < 0 || share.compareTo(members.get(largest).getShare()) > 0)) {
                    largest = i;
                }
            }
            if (largest >= 0) {
                cuts[largest] = cuts[largest].add(pot.setScale(2).subtract(sum));
            }
            return cuts;
        }
    }

    public record PoolRequest(@Size(max = 200) String name) {
    }

    public record PoolMemberRequest(Long personId, Long poolId, BigDecimal share) {
    }

    private final PoolService service;
    private final PersonRepository people;
    private final SheetService sheets;

    public PoolController(PoolService service, PersonRepository people, SheetService sheets) {
        this.service = service;
        this.people = people;
        this.sheets = sheets;
    }

    /** The sheet's pools, in the order they were added. */
    @GetMapping
    @Transactional(readOnly = true)
    public List<PoolView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        return views(sheetId.trim());
    }

    /** Add a pool to the sheet. */
    @PostMapping
    public PoolView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid PoolRequest request) {
        String sid = sheetId.trim();
        return view(sid, service.add(sid, user.trim(), request.name()));
    }

    /** Add a member to a pool with a share: a person, or another pool. */
    @PostMapping("/{poolId}/members")
    public PoolView addMember(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable long poolId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid PoolMemberRequest request) {
        String sid = sheetId.trim();
        Pool pool = service.addMember(sid, user.trim(), poolId, request.personId(), request.poolId(),
                request.share());
        return view(sid, pool);
    }

    private List<PoolView> views(String sheetId) {
        return PoolView.of(service.list(sheetId), people(sheetId), sheets.pot(sheetId));
    }

    private PoolView view(String sheetId, Pool pool) {
        return views(sheetId).stream().filter(v -> v.id() == pool.getId()).findFirst().orElseThrow();
    }

    private Map<Long, Person> people(String sheetId) {
        return people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
    }

    /** A pool or member that cannot be added is refused with the reason, for the screen to show. */
    @ExceptionHandler(PoolRefusedException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> refused(PoolRefusedException e) {
        return Map.of("message", e.getMessage());
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

/** A member of a pool with its share percent: a person (personId), or another pool (poolId). A retired
 *  person counts 0.00 toward the pool's total. */
export interface PoolMemberView {
  personId: number | null;
  poolId: number | null;
  name: string;
  share: string;
  retired: boolean;
  /** Their cut of the pool's pot, two decimals (0.00 when retired); null when the pool is unbalanced or
   *  has no pot. A pool in another has its cut there as its pot; one in none has the sheet's pot. */
  cut: string | null;
}

/** A pool: its members, their total share, and whether that is exactly 100.00. */
/** A member to add: a person or another pool, by id. */
export type PoolMemberChoice = { personId: number } | { poolId: number };

export interface PoolView {
  id: number;
  name: string;
  members: PoolMemberView[];
  totalShare: string;
  balanced: boolean;
}

const SHARE = /^\d{1,3}(\.\d{1,2})?$/;

// The active sheet's pools, re-read from the server each time the sheet is loaded.
@Injectable({ providedIn: 'root' })
export class Pools {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** In the order they were added. */
  readonly pools = signal<PoolView[]>([]);
  private loads = 0;

  /** Re-read the active sheet's pools from the server; an error message when that failed. */
  async load(): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const load = ++this.loads;
    this.pools.set([]);
    if (!user || !sid) return null;
    try {
      const pools = await firstValueFrom(this.http.get<PoolView[]>(this.url(sid), { headers: { 'X-User': user } }));
      if (load === this.loads) this.pools.set(pools);
      return null;
    } catch (e) {
      return e instanceof HttpErrorResponse ? `Could not load pools (${e.status}).` : 'Could not load pools.';
    }
  }

  /** Add a pool; an error message when refused (blank, or the name already taken). */
  async add(name: string): Promise<string | null> {
    const n = name.trim();
    if (!n) return 'Enter a pool name.';
    return this.post('', { name: n }, 'add pool');
  }

  /** Add a person or another pool to a pool with a share; an error message when refused (already in it, a
   *  bad share, or a pool that would contain itself, is already in one, or would make a chain too deep). The
   *  pools are re-read after: a pool in another takes its pot from its cut there. */
  async addMember(poolId: number, member: PoolMemberChoice | null, share: string): Promise<string | null> {
    const s = share.trim();
    if (member === null) return 'Choose a person or a pool.';
    if (!SHARE.test(s) || Number(s) <= 0 || Number(s) > 100) {
      return 'Enter a share more than 0.00 and at most 100.00, in two decimals.';
    }
    const err = await this.post(`/${poolId}/members`, { ...member, share: s }, 'add pool member');
    if (!err) await this.reread();
    return err;
  }

  /** Re-read the active sheet's pools without clearing the ones shown meanwhile. */
  private async reread(): Promise<void> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    if (!user || !sid) return;
    const load = ++this.loads;
    try {
      const pools = await firstValueFrom(this.http.get<PoolView[]>(this.url(sid), { headers: { 'X-User': user } }));
      if (load === this.loads && this.session.sheetId() === sid) this.pools.set(pools);
    } catch {
      // the pool just saved is shown already; the rest are re-read on the next load
    }
  }

  private async post(path: string, body: object, what: string): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    if (!user || !sid) return 'Load a sheet first.';
    try {
      const saved = await firstValueFrom(
        this.http.post<PoolView>(this.url(sid) + path, body, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) {
        this.pools.update((ps) =>
          ps.some((p) => p.id === saved.id) ? ps.map((p) => (p.id === saved.id ? saved : p)) : [...ps, saved],
        );
      }
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && typeof e.error?.message === 'string') return e.error.message;
      return e instanceof HttpErrorResponse ? `Could not ${what} (${e.status}).` : `Could not ${what}.`;
    }
  }

  private url(sid: string): string {
    return `/api/sheets/${encodeURIComponent(sid)}/pools`;
  }
}
